xc_microtheory(a65b16517a98b0,x_UniversalVocabularyMt).
xc_source_file(a65b16517a98b0,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
