xc_mapping_rows(a65b16517a9b66,[]).
x_comment(x_BinarySituationPredicate,"This is the collection of #$BinaryPredicates that relate a #$Situation, as their first arguments, to an instance of #$Thing, as their second arguments.  Note that this means that any #$BinaryPredicate relating a temporal situation to anything at all, whether involved in the situation or not, is an instance of this collection. Thus, this is the broadest #$PredicateType for binary predicates whose first arguments are temporal situations.") :- x_cid(a65b16517a9b67).
xc_microtheory(a65b16517a9b67,x_UniversalVocabularyMt).
xc_source_file(a65b16517a9b67,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
