xc_kb_names(a65b16517a9c49,[]).
xc_mapping_rows(a65b16517a9c49,[]).
x_comment('x_foreignKeyMap-Cascade',"This specialization of #$foreignKeyMap entails an additional\nconstraint on deleting or modifying the rows of the\nreferenced schema. That is (#$foreignKeyMap-Cascade REFERENCED_SCHEMA\nREFERENCED_KEY REFERENCING_SCHEMA REFERENCING_FIELD_LIST) means in\naddition to the constraints inherited from #$foreignKeyMap, deleting a\nrow of REFERENCED_SCHEMA also deletes any rows of REFERENCING_SCHEMA\nwhich reference it. Contrast this behavior with\n#$foreignKeyMap-Restrict, #$foreignKeyMap-SetNull, and #$foreignKeyMap-SetDefault.") :- x_cid(a65b16517a9c4a).
xc_microtheory(a65b16517a9c4a,x_UniversalVocabularyMt).
