xc_kb_names(a65b16517a9d9b,[]).
xc_mapping_rows(a65b16517a9d9b,[]).
x_comment(x_dislikesCuisine,"A #$LikesPredicate and a specialization of #$dislikesType (q.v.). (#$dislikesCuisine AGENT CUISINE) means that AGENT generally dislikes to partake of CUISINE.  Thus, there are few if any dishes within CUISINE that AGENT enjoys, and at least several that s/he actively dislikes.  Cf. #$likesCuisine.") :- x_cid(a65b16517a9d9c).
xc_microtheory(a65b16517a9d9c,x_UniversalVocabularyMt).
