xc_mapping_rows(a65b16517a9dd7,[]).
x_comment(x_injuryConditionToPartType,"A #$FunctionalPredicate that relates a type of\n#$InjuryCondition to the type of #$OrganismPart injured. (#$injuryConditionToPartType CONDITION ORG-PART) means that every\ninstance of CONDITION is an injury to an instance of ORG-PART.  Thus, (#$injuryConditionToPartType BrainInjury Brain) means that every instance of #$BrainInjury is an injury affecting some organism's #$Brain.") :- x_cid(a65b16517a9dd8).
xc_microtheory(a65b16517a9dd8,x_UniversalVocabularyMt).
xc_source_file(a65b16517a9dd8,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
