x_comment(x_hourOfTimeOfDay,"#$hourOfTimeOfDay is the corresponding predicate to the function #$TimeOfDayFn. An assertion of the form (#$hourOfTimeOfDay TIMEOFDAY HOUR MINUTE) asserts that the type TIMEOFDAY is composed out of the #$HourOfDayType HOUR and the #$MinuteOfHourType MINUTE. So, (#$hourOfTimeOfDay (#$TimeOfDayFn #$TimeOfDay-11PM (#$MinuteOfHourFn 12)) #$TimeOfDay-11PM (#$MinuteOfHourFn 12)) states that  (#$TimeOfDayFn #$TimeOfDay-11PM (#$MinuteOfHourFn 12)) is functionally composed out of the #$HourOfDayType #$TimeOfDay-11PM and the #$MinuteOfHourType  (#$MinuteOfHourFn 12). So, it represents the collection of all the #$CalendarMinutes that are the twelfth minute of the 11th hour of some instance of #$TimeOfDay-PM.") :- x_cid(a65b16517aa090).
xc_microtheory(a65b16517aa090,x_UniversalVocabularyMt).
xc_source_file(a65b16517aa090,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517aa090,4395).
xc_kb_names(a65b16517aa090,[]).
xc_mapping_rows(a65b16517aa090,[]).
x_comment(x_typeOfTimeOfHour,"#$typeOfTimeOfHour is the corresponding predicate to the function #$TimeOfHourFn. An assertion of the form (#$typeOfTimeOfHour TIMEOFHOUR MINUTE SECOND) states that the #$TimeOfHourType TIMEOFHOUR is composed out of the #$MinuteOfHourType MINUTE and the #$SecondOfMinuteType SECOND. So, (#$typeOfTimeOfHour (#$TimeOfHourFn (#$MinuteOfHourFn 12) (#$SecondOfMinuteFn 12)) (#$MinuteOfHourFn 12) (#$SecondOfMinuteFn 12)) states that (#$TimeOfHourFn (#$MinuteOfHourFn 12) (#$SecondOfMinuteFn 12)) denotes the collection of every #$CalendarSecond that is the twelfth #$CalendarSecond of the twelfth #$CalendarMinute of some #$CalendarHour.") :- x_cid(a65b16517aa091).
xc_microtheory(a65b16517aa091,x_UniversalVocabularyMt).
xc_source_file(a65b16517aa091,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517aa091,4396).
