xc_kb_names(a65b16517aa1af,[]).
xc_mapping_rows(a65b16517aa1af,[]).
x_comment(x_sentenceHasClarificationSet,"An instance of #$StrictlyFunctionalSlot, #$sentenceHasClarificationSet relates a sentence to the set of all sentences that are reasonable clarifications of that sentence.  More formally, (#$sentenceHasClarificationSet SENTENCE SET) says that each element SET is a sentence S such that (#$sentenceHasClarificationOptions SENTENCE S).") :- x_cid(a65b16517aa1b0).
xc_microtheory(a65b16517aa1b0,x_UniversalVocabularyMt).
