xc_mapping_rows(a65b16517aa22c,[]).
x_comment(x_superiorTypeWRTCriterion,"An assertion of the form (#$superiorTypeWRTCriterion TYPE1 TYPE2 CRIT) states that with respect to the instance of #$EvaluativeCriterion CRIT, it is 'better' to be an instance of TYPE1 than TYPE2.") :- x_cid(a65b16517aa22d).
xc_microtheory(a65b16517aa22d,x_UniversalVocabularyMt).
