xc_mapping_rows(a65b16517aa234,[]).
x_comment(x_CycKBTermRank,"A collection representing the sub-collection of #$EvaluatedNumericalRating whose instances represent the overall connectivity of a #$CycLTerm either to the whole of the relevant instance of #$CycKB or to a particular set of #$CycLTerm.") :- x_cid(a65b16517aa235).
xc_microtheory(a65b16517aa235,x_UniversalVocabularyMt).
xc_source_file(a65b16517aa235,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
