xc_mapping_rows(a65b16517aa2cb,[]).
x_comment(x_taskConstraints,"An assertion of the form (#$taskConstraints TASK CONSTRAINT) asserts that the contents of CONSTRAINT, an instance of #$TaskState, represent some kind of normative constraint on the performance of TASK, a type of #$PurposefulAction.  If any of the assertions contained in CONSTRAINT are false during the performance of TASK, then TASK has violated CONSTRAINT.  The contents of CONSTRAINT could include any number of different things: deadlines, budgets, codes of conduct, etc.") :- x_cid(a65b16517aa2cc).
xc_microtheory(a65b16517aa2cc,x_UniversalVocabularyMt).
xc_source_file(a65b16517aa2cc,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517aa2cc,5559).
xc_kb_names(a65b16517aa2cc,[]).
xc_mapping_rows(a65b16517aa2cc,[]).
x_comment(x_taskPrerequisites,"An assertion of the form (#$taskPrerequisites TASK STATE) asserts that the contents of STATE, an instance of #$TaskState, must be true before TASK, a type of #$PurposefulAction, can be performed.") :- x_cid(a65b16517aa2cd).
xc_microtheory(a65b16517aa2cd,x_UniversalVocabularyMt).
xc_source_file(a65b16517aa2cd,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
