xc_mapping_rows(a65b16517aa2d0,[]).
x_comment(x_goalSupportsGoal,"An assertion of the form (#$goalSupportsGoal GOAL1 GOAL2) asserts that the #$TaskState GOAL1 exists as a desired or intended state of affairs because such a state of affairs is believed to aid in the achievement of #$TaskState GOAL2.") :- x_cid(a65b16517aa2d1).
xc_microtheory(a65b16517aa2d1,x_UniversalVocabularyMt).
