xc_mapping_rows(a65b16517aa2d8,[]).
x_comment(x_taskPostConditions,"An assertion of the form (#$taskPostConditions TASK POST) asserts that TASK, a type of #$PurposefulAction, is expected to make true all of the assertions in POST, an instance of #$TaskState.") :- x_cid(a65b16517aa2d9).
xc_microtheory(a65b16517aa2d9,x_UniversalVocabularyMt).
xc_source_file(a65b16517aa2d9,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
