xc_mapping_rows(a65b16517aa358,[]).
x_comment(x_PowerPointPresentation,"A specialization of #$SlideshowPresentation each instance of which is a performance of a #$Slideshow-CW done on a computer running the application #$MSPowerPoint, and possibly accompanied by \"live\" oral commentary from the presenter.") :- x_cid(a65b16517aa359).
xc_microtheory(a65b16517aa359,x_UniversalVocabularyMt).
xc_source_file(a65b16517aa359,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
