xc_mapping_rows(a65b16517aa428,[]).
x_comment('x_Valuable-PersonalPossession',"An instance of #$ArtifactTypeByGenericCategory.  Each instance of #$Valuable-PersonalPossession is a relatively small, relatively valuable #$PortableObject: a personal possession that one might lock away (e.g. in a #$BankVault) for safekeeping.  Notable specializations are #$TenderObject, #$Jewelry, and #$PersonalSetOfKeys.") :- x_cid(a65b16517aa429).
xc_microtheory(a65b16517aa429,x_UniversalVocabularyMt).
xc_source_file(a65b16517aa429,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
