xc_mapping_rows(a65b16517aa453,[]).
x_comment(x_genlStrategies,"A specialization of #$generalizations. (#$genlStrategies REFINEMENT STRATEGY) says that the REFINEMENT, an instance of #$Strategy is a refinement of the instance of #$Strategy STRATEGY.  The \"is a refinement of\" relationhip is understood as follows: for any event EXE that is an execution of REFINEMENT, EXE is thereby an execution of STRATEGY.") :- x_cid(a65b16517aa454).
xc_microtheory(a65b16517aa454,x_UniversalVocabularyMt).
xc_source_file(a65b16517aa454,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
