xc_mapping_rows(a65b16517aa45e,[]).
x_comment(x_assignmentIterationCount,"An assertion of the form (#$assignmentIterationCount ASSIGN N) is used to relate an instance of of #$IteratedAssignment ASSIGN to an instance of #$PositiveInteger N.  Specifically, this states that the task specified by ASSIGN must be accomplished N times in order to satisfy ASSIGN.") :- x_cid(a65b16517aa45f).
xc_microtheory(a65b16517aa45f,x_UniversalVocabularyMt).
xc_source_file(a65b16517aa45f,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517aa45f,6418).
