xc_mapping_rows(a65b16517aa58a,[]).
x_comment(x_siblingSpecifications,"An assertion of the form (#$siblingSpecifications SIT-SPEC1 and SIT-SPEC2) states that the two instances of #$SituationSpecification SIT-SPEC1 and SIT-SPEC2 are both representations of the same sub-collection of #$Situation.  That is, there exists a collection SIT-TYPE for which the assertions (#$sitTypeHasSpecification SIT-TYPE SIT-SPEC1) and (#$sitTypeHasSpecification SIT-TYPE SIT-SPEC2) are both true.") :- x_cid(a65b16517aa58b).
xc_microtheory(a65b16517aa58b,x_UniversalVocabularyMt).
xc_source_file(a65b16517aa58b,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
