xc_mapping_rows(a65b16517aa932,[]).
x_disjointWith('x_GeneralizedQuantifier-RightMonotone','x_GeneralizedQuantifier-NonMonotone') :- x_cid(a65b16517aa933).
xc_microtheory(a65b16517aa933,x_UniversalVocabularyMt).
xc_source_file(a65b16517aa933,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
