xc_mapping_rows(a65b16517aad60,[]).
x_comment(x_policyForAgent,"<code>(#$policyForAgent POLICY AGENT)</code> means that the #$Policy <code>POLICY</code> is \"for\" the #$IntelligentAgent <code>AGENT</code>, in the sense that <code>AGENT</code> is who is responsible for according with <code>POLICY</code>.  The notion of <i>responsibility</i> here is weaker than obligation: it may be my policy to go to the gym three times a week: in such a case I am not obligated to go to the gym three times a week, but I am in a weak sense still responsible for according with the policy.") :- x_cid(a65b16517aad61).
xc_microtheory(a65b16517aad61,x_UniversalVocabularyMt).
xc_source_file(a65b16517aad61,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517aad61,10295).
xc_kb_names(a65b16517aad61,[]).
xc_mapping_rows(a65b16517aad61,[]).
x_comment(x_likelySuspects,"A predicate used to relate actions to agents who may be perpetrators of those actions (but are not known to be performers of the actions).  <code>(#$likelySuspects ACTION AGENT)</code> means that <code>AGENT</code> is not known to be the performer of <code>ACTION</code>, but nonetheless is considered to be relatively likely to be the performer of <code>ACTION</code>.") :- x_cid(a65b16517aad62).
xc_microtheory(a65b16517aad62,x_UniversalVocabularyMt).
