xc_mapping_rows(a65b16517aad62,[]).
x_comment(x_agentTypeGivesSupportToAgentOfCategory,"(#$agentTypeGivesSupportToAgentOfCategory GIVER-TYPE RECEIVER CATEGORY) means that there exists at least instance GIVER of GIVER-TYPE such that  (#$givesSupportToAgent GIVER RECEIVER CATEGORY).") :- x_cid(a65b16517aad63).
xc_microtheory(a65b16517aad63,x_UniversalVocabularyMt).
