xc_mapping_rows(a65b16517aad64,[]).
x_comment(x_adoptionTypeOfNormByAgent,"(#$adoptionTypeOfNormByAgent NORM AGENT ADOPT-TYPE) means that ADOPT-TYPE is the collection of events in which AGENT adopts the norm NORM.") :- x_cid(a65b16517aad65).
xc_microtheory(a65b16517aad65,x_UniversalVocabularyMt).
