xc_mapping_rows(a65b16517aaec6,[]).
x_comment(x_Farmhouse,"A #$Farmhouse is a #$HumanResidence building located on a farm.  It is where the farmers live.") :- x_cid(a65b16517aaec7).
xc_microtheory(a65b16517aaec7,x_UniversalVocabularyMt).
