xc_kb_names(a65b16517aaecb,[]).
xc_mapping_rows(a65b16517aaecb,[]).
x_comment(x_Gorge,"A specialization of #$Crevice-Topographical.  Each instance of #$Gorge is a deep, narrow, steep-walled passage.  Also known as a <i>ravine</i>.") :- x_cid(a65b16517aaecc).
xc_microtheory(a65b16517aaecc,x_UniversalVocabularyMt).
