xc_kb_names(a65b16517aafab,[]).
xc_mapping_rows(a65b16517aafab,[]).
x_comment(x_SetOrCollectionTypeByCardinality,"A collection of collections of sets or collections.  Each instance of #$SetOrCollectionTypeByCardinality is the collection of all set-or-collections with a particular cardinality, ranging from 0 (see #$EmptySetOrCollection) to aleph-0 or #$PlusInfinity (see #$DenumerableSetOrCollection).  For cardinalities not explicitly represented as reified collections, use #$CardinalityTypeFn.") :- x_cid(a65b16517aafac).
xc_microtheory(a65b16517aafac,x_UniversalVocabularyMt).
