xc_mapping_rows(a65b16517ab3fa,[]).
x_comment(x_dateInRangePredDefinedForCalendarCoveringType,"An instance of #$StrictlyFunctionalSlot that relates an instance of #$DateInRangePredicate to the unique instance of #$CalendarCoveringType that is implicit in the date-granularity implicitly defined for that predicate.  For example, (#$dateInRangePredDefinedForCalendarCoveringType #$yearInRange #$CalendarYear) means that the #$yearInRange relation holds only between dates that are years.") :- x_cid(a65b16517ab3fb).
xc_microtheory(a65b16517ab3fb,x_UniversalVocabularyMt).
