xc_mapping_rows(a65b16517ab5a0,[]).
x_comment(x_temporallyIntersectingEntryFormatInArgs,"An instance of #$SpecificEntryFormatPredicate (q.v.) that is used only with argument-places that are constrained to instances (see #$argIsa) of #$TemporallyExistingThing (q.v.).  (#$temporallyIntersectingEntryFormatInArgs PRED N) means that, for any particular way of fixing the other arguments to PRED besides the Nth, for any two temporally existing things such that if either one is taken as the Nth argument to PRED, those temporally existing things must be such that they temporally intersect with one another (see #$temporallyIntersects).  That is, if the sequences <... ARGN ...> and <... ARGN-PRIME ...> differ at most in their Nth items and both (PRED ... ARGN ...) and (PRED ... ARGN-PRIME ...) hold, then if (#$argIsa PRED N #$TemporallyExistingThing) then (#$temporallyIntersects ARGN ARGN-PRIME) holds (i.e. (#$not (#$temporallyDisjoint ARGN ARGN-PRIME)) holds).") :- x_cid(a65b16517ab5a1).
xc_microtheory(a65b16517ab5a1,x_UniversalVocabularyMt).
xc_source_file(a65b16517ab5a1,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517ab5a1,13472).
xc_kb_names(a65b16517ab5a1,[]).
xc_mapping_rows(a65b16517ab5a1,[]).
x_comment(x_spatiallyIntersectingEntryFormatInArgs,"An instance of #$SpecificEntryFormatPredicate (q.v.) that is used only with argument-places that are constrained to instances (see #$argIsa) of #$SpatialThing (q.v.). (#$spatiallyIntersectingEntryFormatInArgs PRED N) means that, for any particular way of fixing the other arguments to PRED besides the Nth, for any two spatial things such that if either one is taken as the Nth argument to PRED, those spatial things must be such that they spatially intersect with one another (see#$spatiallyIntersects). That is, if the sequences <... ARGN ...> and <... ARGN-PRIME ...> differ at most in their Nth items and both (PRED ... ARGN ...) and (PRED ... ARGN-PRIME ...) hold, then if (#$argIsa PRED N #$SpatialThing) then (#$spatiallyIntersects ARGN ARGN-PRIME) holds (i.e. (#$not (#$spatiallyDisjoint ARGN ARGN-PRIME)) holds).") :- x_cid(a65b16517ab5a2).
xc_microtheory(a65b16517ab5a2,x_UniversalVocabularyMt).
