xc_mapping_rows(a65b16517ab68b,[]).
x_comment('x_GeographicalLine-Intangible',"A specialization of both #$GeographicalThing-Intangible and #$LineSegment (qq.v.).  This is the collection of one-dimensional intangible geographical lines, fixed-location or otherwise.  Its specializations include #$LatitudeLine, #$LineOfMilitaryForces, and #$GeopoliticalBorder.") :- x_cid(a65b16517ab68c).
xc_microtheory(a65b16517ab68c,x_UniversalVocabularyMt).
xc_source_file(a65b16517ab68c,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
