xc_mapping_rows(a65b16517ab73e,[]).
x_comment(x_loggedInToAppOnComputer,"An assertion of the form (#$loggedInToAppOnComputer AGENT PROGRAM COMPUTER) states that the #$IntelligentAgent AGENT is logged in to #$ComputerProgram-CW  PROGRAM using the #$Computer COMPUTER. This is a #$TemporallyQualifiableRelation.") :- x_cid(a65b16517ab73f).
