xc_mapping_rows(a65b16517ab77d,[]).
x_comment(x_coplanarLines,"A symmetric, reflexive #$RelativeLocationalPredicates that relates straight lines (see #$Line-Straight) that lie in the same plane.\n<code>(#$coplanarLines LINE1 LINE2)</code> is true if and only if there is a\n#$Plane that #$spatiallySubsumes both <code>LINE1</code> and <code>LINE2</code>.\n<p>\nSee also #$coplanarPoints.") :- x_cid(a65b16517ab77e).
xc_microtheory(a65b16517ab77e,x_UniversalVocabularyMt).
