xc_mapping_rows(a65b16517ab886,[]).
x_comment(x_CruciformObject,"A specialization of #$Artifact.  Each instance of #$CruciformObject is an artifact consisting of an upright beam and a transverse beam, with the two beams roughly orthogonal to each other.  Examples include Christian crosses.") :- x_cid(a65b16517ab887).
xc_microtheory(a65b16517ab887,x_UniversalVocabularyMt).
xc_source_file(a65b16517ab887,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
