xc_mapping_rows(a65b16517ab8d1,[]).
x_comment(x_UnitedStatesMilitaryOrganization,"A specialization of #$ModernMilitaryOrganization.  This collection includes the (contemporary) U.S. military forces: the #$UnitedStatesArmy, #$UnitedStatesNavy, #$UnitedStatesAirForce, #$UnitedStatesMarineCorps (and, during wartime, the #$UnitedStatesCoastGuard), as well as all of their #$subOrganizations.  Each  US military organization is a suborganization of the #$USExecutiveBranch.") :- x_cid(a65b16517ab8d2).
xc_microtheory(a65b16517ab8d2,x_UniversalVocabularyMt).
