xc_mapping_rows(a65b16517ab955,[]).
x_comment('x_Army-MilitaryEchelon',"A #$MilitaryUnitTypeByEchelon and a subcollection of #$ModernMilitaryUnit-Deployable.  #$Army-MilitaryEchelon is and an instance of #$USArmyEchelon.  \n<p>\nIn the US Army, an army consists of 50,000 or more soldiers, is made up of two or more corps (see #$Corps-MilitaryEchelon), and is commanded by a lieutenant general or higher.\n<p>\nNote that army units have not been deployed by the #$UnitedStatesArmy since World War II.  Also cf. #$Army-BranchOfService.") :- x_cid(a65b16517ab956).
xc_microtheory(a65b16517ab956,x_UniversalVocabularyMt).
xc_source_file(a65b16517ab956,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
