xc_mapping_rows(a65b16517abb53,[]).
x_comment(x_GeodesyConcept,"Instances of #$GeodesyConcept are concepts which are included in the domain of #$Geodesy; therefore, #$Spheroid models of the Earth, map projections, and coordinate systems would be instances of this collection.") :- x_cid(a65b16517abb54).
xc_microtheory(a65b16517abb54,x_UniversalVocabularyMt).
