xc_mapping_rows(a65b16517abb57,[]).
x_comment(x_hasPortalToRegion,"A #$CoexistingObjectsPredicate that is a specialization of both #$near and #$temporallyCoexist.  <code>(#$hasPortalToRegion OBJ1 OBJ2)</code> means that <code>OBJ1</code> is connected to <code>OBJ2</code> by some type of #$Portal (q.v.).  For example, \n<code>(#$hasPortalToRegion MyMasterBedroom MyMasterBathroom)</code>.  See also \n#$portalConnectsRegions.") :- x_cid(a65b16517abb58).
xc_microtheory(a65b16517abb58,x_UniversalVocabularyMt).
xc_source_file(a65b16517abb58,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
