xc_mapping_rows(a65b16517abbbb,[]).
x_comment(x_UDSForParseTreeFn,"(UDSForParseTreeFn TREE). denotes the unit discourse\nstructure associated with the #$CycParseTree TREE.") :- x_cid(a65b16517abbbc).
xc_microtheory(a65b16517abbbc,x_UniversalVocabularyMt).
xc_source_file(a65b16517abbbc,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
