xc_mapping_rows(a65b16517abc5f,[]).
x_comment('x_oughtToBe-SitTypeRolePlayerOfType',"(#$oughtToBe-SitTypeRolePlayerOfType <b>SIT-TYPE</b> <b>ROLE</b>\n<b>OBLIGATORY-TYPE</b>) means that, given any instance <b>INS</b> of <b>SIT-TYPE</b>, at\nleast one object playing <b>ROLE</b> in <b>INS</b> should be an instance of\n<b>OBLIGATORY-TYPE</b>. That is, there should be an instance <b>OBLIGATORY-INS</b>\nof <b>OBLIGATORY-TYPE</b> such that\n(<b>ROLE</b> <b>INS</b> <b>OBLIGATORY-INS</b>). Assertions involving this predicate --\nwhich specify what <i>should</i> be the case -- should be made in a\nnormative context, e.g., one that reflects the contents of a\nparticular #$CodeOfConduct.") :- x_cid(a65b16517abc60).
xc_microtheory(a65b16517abc60,x_UniversalVocabularyMt).
xc_source_file(a65b16517abc60,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517abc60,17457).
xc_kb_names(a65b16517abc60,[]).
xc_mapping_rows(a65b16517abc60,[]).
x_comment('x_forbidden-SitTypeRolePlayerOfType',"(#$forbidden-SitTypeRolePlayerOfType <b>SIT-TYPE</b> <b>ROLE</b>\n<b>FORBIDDEN-TYPE</b>) means that in no instance of <b>SIT-TYPE</b>\nshould any instance of <b>FORBIDDEN-TYPE</b> play\n<b>ROLE</b>.  That is, there should be no instance <b>INS</b> of\n<b>SIT-TYPE</b> and <b>FORBIDDEN-INS</b> of <b>FORBIDDEN-TYPE</b> such\nthat\n(<b>ROLE</b> <b>INS</b> <b>FORBIDDEN-INS</b>).  Assertions involving this predicate --\nwhich specify what <i>should</i> not be the case -- should be made in\na normative context, e.g., one that reflects the contents of a\nparticular #$CodeOfConduct.") :- x_cid(a65b16517abc61).
xc_microtheory(a65b16517abc61,x_UniversalVocabularyMt).
xc_source_file(a65b16517abc61,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517abc61,17466).
xc_kb_names(a65b16517abc61,[]).
xc_mapping_rows(a65b16517abc61,[]).
x_comment('x_oughtToBe-SitRelationToType',"(#$oughtToBe-SitRelationToType <b>SIT</b> <b>BIN-PRED</b>\n<b>OBLIGATORY-TYPE</b>) means that there should be an instance\n<b>OBLIGATORY-INS</b> of <b>OBLIGATORY-TYPE</b> such that\n(<b>BIN-PRED</b> <b>SIT</b> <b>OBLIGATORY-INS</b>).\n#$oughtToBe-SitRelationToType is a very general requirement predicate\nmost useful for querying.  Statements of requirements should usually\nemploy specializations of this predicate.  E.g., if <b>BIN-PRED</b> is\nan instance of #$BinaryRolePredicate, use\n#$oughtToBe-SitRolePlayerOfType.  If <b>OBLIGATORY-INS</b> is a type\nof #$Situation (e.g., one an instance of which should be a #$subEvents\nof <b>SIT</b>), use #$oughtToBe-SitRelationToSitType.") :- x_cid(a65b16517abc62).
xc_microtheory(a65b16517abc62,x_UniversalVocabularyMt).
xc_source_file(a65b16517abc62,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517abc62,17476).
xc_kb_names(a65b16517abc62,[]).
xc_mapping_rows(a65b16517abc62,[]).
x_comment('x_forbidden-SitRolePlayerOfType',"(#$forbidden-SitRolePlayerOfType <b>SIT</b> <b>ROLE</b>\n<b>FORBIDDEN-TYPE</b>) means that no instance of <b>FORBIDDEN-TYPE</b>\nshould play <b>ROLE</b> in <b>SIT</b>.  In other words, there should\nbe no <b>FORBIDDEN-INS</b> such that (<b>ROLE</b> <b>SIT</b>\n<b>FORBIDDEN-INS</b>). Assertions involving this predicate -- which\nspecify what <i>should</i> not be the case -- should be made in a\nnormative context, e.g., one that reflects the contents of a\nparticular #$CodeOfConduct. Usually, <b>SIT</b> will be subject to\nsuch a prohibition in virtue of satisfying some general description,\ne.g., one stated in the antecedent of a #$CycLRuleAssertion.") :- x_cid(a65b16517abc63).
xc_microtheory(a65b16517abc63,x_UniversalVocabularyMt).
xc_source_file(a65b16517abc63,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517abc63,17487).
xc_kb_names(a65b16517abc63,[]).
xc_mapping_rows(a65b16517abc63,[]).
x_comment('x_forbidden-SitRelationToType',"(#$forbidden-SitRelationToType <b>SIT</b> <b>BIN-PRED</b> <b>FORBIDDEN-TYPE</b>) means\nthat there should be no instance <b>FORBIDDEN-INS</b> of <b>FORBIDDEN-TYPE</b> such\nthat (<b>BIN-PRED</b> <b>SIT</b> <b>FORBIDDEN-INS</b>).  #$forbidden-SitRelationToType is a\nvery general prohibition predicate most useful for querying.\nStatements of prohibitions should usually employ specializations of\nthis predicate.  E.g., if <b>BIN-PRED</b> is an instance of\n#$BinaryRolePredicate, use #$forbidden-SitRolePlayerOfType.  If\n<b>FORBIDDEN-INS</b> is a type of #$Situation (e.g., one no instance of which\nmay be a #$subEvents of <b>SIT</b>), use #$forbidden-SitRelationToSitType.") :- x_cid(a65b16517abc64).
xc_microtheory(a65b16517abc64,x_UniversalVocabularyMt).
xc_source_file(a65b16517abc64,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
