x_comment(x_ComplementaryAngleFn,"If <code>ANGLE</code> is an #$AngularDistance that is greater or equal to <code>(#$Degree-UnitOfAngularMeasure 0)</code> and less than or equal to <code>(#$Degree-UnitOfAngularMeasure 90)</code> then <code>(#$ComplementaryAngleFn ANGLE)</code> returns the <i>complementary angle</i> of <code>ANGLE</code>, that is <code>90 - ANGLE</code> degrees. Note that this function is defined only for angular distances within the above stated bounds, otherwise it is #$undefined.") :- x_cid(a65b16517abe13).
xc_microtheory(a65b16517abe13,x_UniversalVocabularyMt).
xc_source_file(a65b16517abe13,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517abe13,18373).
xc_kb_names(a65b16517abe13,[]).
xc_mapping_rows(a65b16517abe13,[]).
x_comment(x_SupplementaryAngleFn,"If <code>ANGLE</code> is an #$AngularDistance that is greater than or equal to <code>(#$Degree-UnitOfAngularMeasure 0)</code> and less than or equal to <code>(#$Degree-UnitOfAngularMeasure 180)</code> then <code>(#$SupplementaryAngleFn ANGLE)</code> returns the <i>supplementary angle</i> of <code>ANGLE</code>, that is <code>180 - ANGLE</code> degrees. Note that this function is defined only for angular distances within the above stated bounds, otherwise it is #$undefined.") :- x_cid(a65b16517abe14).
xc_microtheory(a65b16517abe14,x_UniversalVocabularyMt).
xc_source_file(a65b16517abe14,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
