xc_mapping_rows(a65b16517abe15,[]).
x_comment(x_pointOfIntersectingLines,"<code>(#$pointOfIntersectingLines P LINE1 LINE2)</code> means that the straight lines <code>LINE1</code> and <code>LINE2</code> intersect at the point <code>P</code>.") :- x_cid(a65b16517abe16).
xc_microtheory(a65b16517abe16,x_UniversalVocabularyMt).
