xc_kb_names(a65b16517abe19,[]).
xc_mapping_rows(a65b16517abe19,[]).
x_comment(x_tangentLineAtPointOnCurve,"A line, <code>LINE</code> is <i>tangent</i> to a curve, <code>CURVE</code> at a point, <code>POINT</code> if and only if both <code>LINE</code> and <code>CURVE</code> pass through <code>POINT</code> with the same direction and slope. In Cyc, this relation is stated as <code>(#$tangentLineAtPointOnCurve POINT LINE CURVE)</code>.") :- x_cid(a65b16517abe1a).
xc_microtheory(a65b16517abe1a,x_UniversalVocabularyMt).
xc_source_file(a65b16517abe1a,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
