xc_mapping_rows(a65b16517abe1a,[]).
x_comment(x_ellipsoidalSection,"An ellipsoidal section is the curve formed by the intersection of a plane with an ellipsoid. Excluding the degenerate case of the plane tangent to the ellipsoid, an ellipsoidal section is always an ellipse. We exclude the degenerate case from consideration in the predicate #$ellipsoidalSection. So <code>(#$ellipsoidalSection ELLIPSE ELLIPSOID)</code> means that the #$Ellipse, <code>ELLIPSE</code> is a curve formed by the intersection of the #$Ellipsoid, <code>ELLIPSOID</code> with a unique #$Plane.") :- x_cid(a65b16517abe1b).
xc_microtheory(a65b16517abe1b,x_UniversalVocabularyMt).
xc_source_file(a65b16517abe1b,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517abe1b,18388).
xc_kb_names(a65b16517abe1b,[]).
xc_mapping_rows(a65b16517abe1b,[]).
x_comment(x_spheroidalSection,"An spheroidal section is the curve formed by the intersection of a plane with a spheroid. Excluding the degenerate case of the plane tangent to the spheroid, a spheroidal section is always an ellipse. If the plane is perpendicular to the polar axis of the spheroid, the intersection is a circle. We exclude the degenerate case from consideration in the predicate #$spheroidalSection. So <code>(#$spheroidalSection ELLIPSE SPHEROID)</code> means that the #$Ellipse, <code>ELLIPSE</code>, is a curve formed by the intersection of the #$Spheroid, <code>SPHEROID</code>, with a unique #$Plane.") :- x_cid(a65b16517abe1c).
xc_microtheory(a65b16517abe1c,x_UniversalVocabularyMt).
xc_source_file(a65b16517abe1c,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517abe1c,18389).
xc_kb_names(a65b16517abe1c,[]).
xc_mapping_rows(a65b16517abe1c,[]).
x_comment(x_sphericSection,"A spheric section is the curve formed by the intersection of a plane with a sphere. Excluding the degenerate case of the plane tangent to the sphere, all spheric sections are circles. We exclude the degenerate case from consideration in the predicate #$sphericSection. So <code>(#$sphericSection CIRCLE SPHERE)</code> means that the #$Circle, <code>CIRCLE</code>, is a curve formed by the intersection of the #$Sphere, <code>SPHERE</code>, with a unique #$Plane.") :- x_cid(a65b16517abe1d).
xc_microtheory(a65b16517abe1d,x_UniversalVocabularyMt).
xc_source_file(a65b16517abe1d,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
