xc_mapping_rows(a65b16517abe22,[]).
x_comment(x_smallCircleOfSphere,"A <i>small circle</i> is a section of a sphere (see #$sphericSection) that is not centered at the same point as the sphere. <code>(#$smallCircleOfSphere CIRCLE SPHERE)</code> means that the #$Circle, <code>CIRCLE</code> is a small circle of the #$Sphere, <code>SPHERE</code>. See also #$greatCircleOfSphere.") :- x_cid(a65b16517abe23).
xc_microtheory(a65b16517abe23,x_UniversalVocabularyMt).
