xc_mapping_rows(a65b16517abe57,[]).
x_comment(x_CrudeFn,"An instance of #$CollectionDenotingFunction. When applied to an instance <code>STUFF-TYPE</code> of #$ExistingStuffType, #$CrudeFn returns all instances of <code>STUFF-TYPE</code> that are products entering a market for the first time that are not manufactured, processed or refined, and are not sold directly to consumers. ") :- x_cid(a65b16517abe58).
xc_microtheory(a65b16517abe58,x_UniversalVocabularyMt).
xc_source_file(a65b16517abe58,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517abe58,18511).
