xc_mapping_rows(a65b16517abe58,[]).
x_comment(x_signalsEvent,"(#$signalsEvent <b>SIGNAL-EVENT</b> <b>EVENT</b>) means that\n<b>SIGNAL-EVENT</b> signals the existence or occurrence of\n<b>EVENT</b>.  The type of 'signaling' relation\nintended here is conventional, i.e., is determined by a convention which dictates that\nevents of one type (i.e., one to which <b>SIGNAL-EVENT</b> belongs)\nindicate the occurrence of events of another type.\n(The relevant convention here may be unwritten, limited to a small\ngroup of agents, temporary, etc.).  For example, the selection of a\nnew pope by the #$CollegeOfCardinals is signaled, in accordance with\nChurch law, by white smoke issuing from the chimney of the\n#$SistineChapel.  No temporal order is entailed by this general\nrelation -- <b>SIGNAL-EVENT</b> may signal that <b>EVENT</b> has\noccurred, will occur, or has started.") :- x_cid(a65b16517abe59).
xc_microtheory(a65b16517abe59,x_UniversalVocabularyMt).
xc_source_file(a65b16517abe59,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517abe59,18512).
xc_kb_names(a65b16517abe59,[]).
xc_mapping_rows(a65b16517abe59,[]).
x_comment(x_permittee,"'(#$permittee GRANT AGENT)' means that AGENT is the #$IntelligentAgent who is granted permission in the #$GrantingPermission GRANT.") :- x_cid(a65b16517abe5a).
xc_microtheory(a65b16517abe5a,x_UniversalVocabularyMt).
xc_source_file(a65b16517abe5a,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
