xc_mapping_rows(a65b16517abe5a,[]).
x_comment(x_agreementRequires,"This quaternary predicate is used to indicate that a particular agent is required to play a particular role in a particular kind of situation under the terms of a particular agreement.  <code>(#$agreementRequires AGREEMENT AGENT SIT-TYPE ROLE)</code> means that the #$Agreement <code>AGREEMENT</code> specifies that the #$IntelligentAgent <code>AGENT</code> is required to play the #$Role <code>ROLE</code> in some situation that is an instance of the subcollection of #$Situation <code>SIT-TYPE</code>.  For example, a peace accord #$agreementRequires the signatories to withdraw their troops behind specified boundaries.") :- x_cid(a65b16517abe5b).
xc_microtheory(a65b16517abe5b,x_UniversalVocabularyMt).
xc_source_file(a65b16517abe5b,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517abe5b,18526).
