xc_mapping_rows(a65b16517abe5b,[]).
x_comment(x_permittedProp,"(#$permittedProp GP FORM) means that in the #$GrantingPermission event, GP, the doer permits situations described by the formula FORM.") :- x_cid(a65b16517abe5c).
xc_microtheory(a65b16517abe5c,x_UniversalVocabularyMt).
