xc_kb_names(a65b16517abfa7,[]).
xc_mapping_rows(a65b16517abfa7,[]).
x_comment(x_topologyOfTopologicalSpace,"<code>(#$topologyOfTopologicalSpace TOPOLOGY SPACE)</code> means that <code>TOPOLOGY</code> is the #$Topology of the #$TopologicalSpace, <code>SPACE</code>.") :- x_cid(a65b16517abfa8).
xc_microtheory(a65b16517abfa8,x_UniversalVocabularyMt).
xc_source_file(a65b16517abfa8,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
