xc_mapping_rows(a65b16517ac023,[]).
x_comment(x_DrinkingFountain,"An instance of #$ArtifactTypeByGenericCategory.  Each instance of #$DrinkingFountain is a device that releases a (usually upward-arcing) stream of water, from which a person can directly drink.") :- x_cid(a65b16517ac024).
xc_microtheory(a65b16517ac024,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac024,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
