xc_mapping_rows(a65b16517ac06e,[]).
x_comment(x_UnitOfMass,"A specialization of #$UnitOfMeasure and an instance of #$FundamentalUnitType. Each function in this collection returns instances of #$Mass.  For example, (#$Kilogram 5) is the quantity 5 kilograms.") :- x_cid(a65b16517ac06f).
xc_microtheory(a65b16517ac06f,x_UniversalVocabularyMt).
