xc_mapping_rows(a65b16517ac100,[]).
x_comment(x_RegularTopologicalSpace,"A #$RegularTopologicalSpace is a topological space in which every neighborhood of a point contains a closed neighborhood of the same point. See #$neighborhoodOfThingInTopologicalSpace and #$closedSetOfTopologicalSpace.") :- x_cid(a65b16517ac101).
xc_microtheory(a65b16517ac101,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac101,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517ac101,19705).
xc_kb_names(a65b16517ac101,[]).
xc_mapping_rows(a65b16517ac101,[]).
x_comment(x_NormalTopologicalSpace,"A #$NormalTopologicalSpace is a #$TopologicalSpace in which for any two disjoint closed sets <code>C</code> and <code>D</code> there exist disjoint open sets <code>U</code> and <code>V</code> such that <code>C</code> is a subset of <code>U</code> and <code>D</code> is a subset of <code>V</code>. See #$openSetOfTopologicalSpace and #$closedSetOfTopologicalSpace.") :- x_cid(a65b16517ac102).
xc_microtheory(a65b16517ac102,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac102,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517ac102,19706).
xc_kb_names(a65b16517ac102,[]).
xc_mapping_rows(a65b16517ac102,[]).
x_comment('x_T0-TopologicalSpace',"A #$T0-TopologicalSpace is a #$TopologicalSpace in which for any two points <code>X</code> and <code>Y</code> there exists an open set <code>U</code> such that either:\n<p>\n1. <code>X</code> is an element of <code>U</code> and <code>Y</code> is not an element of <code>U</code>, or\n<p>\n2. <code>Y</code> is an element of <code>U</code> and <code>X</code> is not an element of <code>U</code>.\n<p>\n#$T0-TopologicalSpaces are often called <i>Kolmogorov spaces</i>. See also #$openSetOfTopologicalSpace.") :- x_cid(a65b16517ac103).
xc_microtheory(a65b16517ac103,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac103,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517ac103,19707).
xc_kb_names(a65b16517ac103,[]).
xc_mapping_rows(a65b16517ac103,[]).
x_comment('x_T1-TopologicalSpace',"A #$T1-TopologicalSpace is a #$TopologicalSpace in which for any two points <code>X</code> and <code>Y</code> there exist open sets <code>U</code> and <code>V</code> such that\n<p>\n1. <code>X</code> is an element of <code>U</code> and <code>Y</code> is not an element of <code>U</code>, and\n<p>\n2. <code>Y</code> is an element of <code>V</code> and <code>X</code> is not an element of <code>V</code>.\n<p>\n#$T1-TopologicalSpaces are often called <i>Frechet spaces</i>. See also #$openSetOfTopologicalSpace.") :- x_cid(a65b16517ac104).
xc_microtheory(a65b16517ac104,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac104,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517ac104,19714).
xc_kb_names(a65b16517ac104,[]).
xc_mapping_rows(a65b16517ac104,[]).
x_comment('x_T2-TopologicalSpace',"A #$T2-TopologicalSpace is a #$TopologicalSpace in which for any two points <code>X</code> and <code>Y</code> there exist <i>disjoint</i> open sets <code>U</code> and <code>V</code> such that <code>X</code> is an element of <code>U</code>, <code>Y</code> is an element of <code>V</code>. #$T2-TopologicalSpaces are often called <i>Hausdorff spaces</i>. See also #$openSetOfTopologicalSpace.") :- x_cid(a65b16517ac105).
xc_microtheory(a65b16517ac105,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac105,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
