xc_mapping_rows(a65b16517ac27b,[]).
x_comment(x_actsInCapacityAsMember,"(#$actsInCapacityAsMember AGENT OCCUPATION-TYPE ORGANIZATION) holds just in case AGENT is a member of ORGANIZATION and works as OCCUPATION-TYPE for ORGANIZATION.  For instance, asserting the conjunction of (#$isa AGENT #$ComputerScientist) and (#$employees ORGANIZATION AGENT) isn't sufficient to represent the situation where AGENT works as a computer scientist in ORGANIZATION -- the mere conjunction is consistent with the fact that AGENT is a computer scientist somewhere else and moonlights as a janitor for ORGANIZATION.") :- x_cid(a65b16517ac27c).
xc_microtheory(a65b16517ac27c,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac27c,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
