xc_mapping_rows(a65b16517ac29a,[]).
x_comment(x_syntacticNodeSyntacticHead,"<code>(#$syntacticNodeSyntacticHead NODE HEAD)</code> identifies <code>HEAD</code> as the syntactic head of the instance <code>NODE</code> of #$SyntacticNode.  Note that where <code>(#$isa NODE #$LexicalNode)</code>, <code>(#$syntacticNodeSyntacticHead NODE NODE)</code> holds.") :- x_cid(a65b16517ac29b).
xc_microtheory(a65b16517ac29b,x_UniversalVocabularyMt).
