x_comment(x_increasesThroughoutEvent,"This predicate is used to state that the value of a quantity slot increases for a fixed object throughout an event. <code>(#$increasesThroughoutEvent SLOT THING EVENT)</code> is true if and only if for every pair of sub-events <code>SUB1</code> and <code>SUB2</code> of <code>EVENT</code> there exist values <code>VAL1</code> and <code>VAL2</code> such that if\n<pre>\n(#$and\n  (#$startsAfterEndingOf SUB1 SUB2)\n  (#$holdsIn SUB1 (SLOT THING VAL1))\n  (#$holdsIn SUB2 (SLOT THING VAL2)))\n</pre>\nit follows that\n<pre>\n(#$greaterThanOrEqualTo VAL1 VAL2)\n</pre>\nis true. See also #$decreasesThroughoutEvent and #$constantThroughoutEvent.") :- x_cid(a65b16517ac33f).
xc_microtheory(a65b16517ac33f,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac33f,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517ac33f,20777).
xc_kb_names(a65b16517ac33f,[]).
xc_mapping_rows(a65b16517ac33f,[]).
x_comment(x_decreasesThroughoutEvent,"This predicate is used to state that the value of a quantity slot decreases for a fixed object throughout an event. <code>(#$decreasesThroughoutEvent SLOT THING EVENT)</code> is true if and only if for every pair of sub-events <code>SUB1</code> and <code>SUB2</code> of <code>EVENT</code> there exist values <code>VAL1</code> and <code>VAL2</code> such that if\n<pre>\n(#$and\n  (#$startsAfterEndingOf SUB1 SUB2)\n  (#$holdsIn SUB1 (SLOT THING VAL1))\n  (#$holdsIn SUB2 (SLOT THING VAL2)))\n</pre>\nit follows that\n<pre>\n(#$greaterThanOrEqualTo VAL2 VAL1)\n</pre>\nis true. See also #$increasesThroughoutEvent and #$constantThroughoutEvent.") :- x_cid(a65b16517ac340).
xc_microtheory(a65b16517ac340,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac340,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517ac340,20789).
xc_kb_names(a65b16517ac340,[]).
xc_mapping_rows(a65b16517ac340,[]).
x_comment(x_constantThroughoutEvent,"This predicate is used to state that the value of a quantity slot remains constant for a fixed object throughout an event. <code>(#$constantThroughoutEvent SLOT THING EVENT)</code> is true if and only if for every pair of sub-events <code>SUB1</code> and <code>SUB2</code> of <code>EVENT</code> there exist values <code>VAL1</code> and <code>VAL2</code> such that if\n<pre>\n(#$and\n  (#$startsAfterEndingOf SUB1 SUB2)\n  (#$holdsIn SUB1 (SLOT THING VAL1))\n  (#$holdsIn SUB2 (SLOT THING VAL2)))\n</pre>\nit follows that\n<pre>\n(#$numericallyEquals VAL1 VAL2)\n</pre>\nis true. See also #$decreasesThroughoutEvent and #$increasesThroughoutEvent.") :- x_cid(a65b16517ac341).
xc_microtheory(a65b16517ac341,x_UniversalVocabularyMt).
