xc_mapping_rows(a65b16517ac3b5,[]).
x_comment(x_BooleanParameter,"A specialization of #$Parameter. Instances of #$BooleanParameter can have one of two values.  From a logical perspective, this would be #$True and #$False.  However, 0 and 1 will also work.") :- x_cid(a65b16517ac3b6).
xc_microtheory(a65b16517ac3b6,x_UniversalVocabularyMt).
