xc_mapping_rows(a65b16517ac3f1,[]).
x_comment(x_baseWordFormTypeEndingLetters,"<code>(#$baseWordFormTypeEndingLetters TYPE STRING)</code> identifies <code>TYPE</code> as the instance of #$BaseWordFormTypeByEndingLetters each instance of which is a word unit with the ending letters <code>STRING</code>.") :- x_cid(a65b16517ac3f2).
xc_microtheory(a65b16517ac3f2,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac3f2,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
