xc_mapping_rows(a65b16517ac3f4,[]).
x_comment(x_GrassyScrubbyVegetationRegion,"A specialization of #$ScrubbyVegetationRegion. Each #$GrassyScrubbyVegetationRegion is a #$GeographicalRegion that is populated with grasses and short woody plants.") :- x_cid(a65b16517ac3f5).
xc_microtheory(a65b16517ac3f5,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac3f5,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
