xc_mapping_rows(a65b16517ac3fb,[]).
x_comment(x_SecondOrderAdministrativeDivision,"A subdivision of a first order administrative division, such as a county in a state of the United States.") :- x_cid(a65b16517ac3fc).
xc_microtheory(a65b16517ac3fc,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac3fc,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
