xc_kb_names(a65b16517ac3fc,[]).
xc_mapping_rows(a65b16517ac3fc,[]).
x_comment(x_ThirdOrderAdministrativeDivision,"A subdivision of a second order administrative division.") :- x_cid(a65b16517ac3fd).
xc_microtheory(a65b16517ac3fd,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac3fd,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517ac3fd,21109).
xc_kb_names(a65b16517ac3fd,[]).
xc_mapping_rows(a65b16517ac3fd,[]).
x_comment(x_FourthOrderAdministrativeDivision,"A subdivision of a third order administrative division.") :- x_cid(a65b16517ac3fe).
xc_microtheory(a65b16517ac3fe,x_UniversalVocabularyMt).
