xc_mapping_rows(a65b16517ac427,[]).
x_comment(x_WordNetSpeechPart,"A collection of collections.  Each element of #$WordNetSpeechPart is a #$SpeechPart.  As of #$WordNet-Version2_0, this is restricted to #$Noun, #$Verb, #$Adverb, and #$Adjective.  This collection is significant because it allows us to restrict the values that are sent to functions such as #$WNAllCandidateDenotsForWordPOSFn-Default.") :- x_cid(a65b16517ac428).
xc_microtheory(a65b16517ac428,x_UniversalVocabularyMt).
