xc_mapping_rows(a65b16517ac593,[]).
x_comment(x_strategyApplicableToHypothesis,"A sentence of the form (#$strategyApplicableToHypothesis STRATEGY HYP) means that the #$ScoringSoftwareStrategy STRATEGY is relevant to the evaluation of the #$HypotheticalContext HYP.") :- x_cid(a65b16517ac594).
xc_microtheory(a65b16517ac594,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac594,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
