xc_mapping_rows(a65b16517ac595,[]).
x_comment(x_SpaceTransportationEvent,"The collection of all space transportation events.  For each instance TRAN of #$SpaceTransportationEvent, at least a part of the #$Trajectory of #$objectMoving in TRAN must be in the outer space.  Note that #$SpaceTransportationEvent is different from (#$TransportViaFn #$Spacecraft) because the former emphasizes where to find the #$Trajectory while the latter emphasizes what is used as a tool, not to mention instances of the former do not have to have parts on Earth or inside our atmosphere.") :- x_cid(a65b16517ac596).
xc_microtheory(a65b16517ac596,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac596,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517ac596,21991).
xc_kb_names(a65b16517ac596,[]).
xc_mapping_rows(a65b16517ac596,[]).
x_comment(x_parserSpecificationParseCategory,"<code>(#$parserSpecificationParseCategory SPECIFICATION SPEECH-PART)</code> means that in the parser specification <code>SPECIFICATION</code>, only parses that fall into the category <code>SPEECH-PART</code>, an instance of #$SpeechPart, are returned.  For example, if a parse of \"wet\" is performed according to <code>SPECIFICATION</code> such that <code>(#$parserSpecificationParseCategory SPECIFICATION #$Verb)</code> only verbal semantics (as opposed to adjectival, for example) for \"wet\" would be returned.") :- x_cid(a65b16517ac597).
xc_microtheory(a65b16517ac597,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac597,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517ac597,21992).
xc_kb_names(a65b16517ac597,[]).
xc_mapping_rows(a65b16517ac597,[]).
x_comment(x_parserSpecificationPOSPredicate,"<code>(#$parserSpecificationPOSPredicate SPECIFICATION SPEECH-PART-PRED)</code> means that in the parser specification <code>SPECIFICATION</code>, only parses that are consistent with <code>SPEECH-PART-PRED</code>, an instance of #$SpeechPartPredicate, are returned.  For example, if a parse of \"green\" is performed according to <code>SPECIFICATION</code> such that <code>(#$parserSpecificationPOSPredicate SPECIFICATION #$singular)</code>, only semantics licensed by a singular use of \"green\"(as opposed to those for #$regularDegree, for example) would be returned.") :- x_cid(a65b16517ac598).
xc_microtheory(a65b16517ac598,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac598,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517ac598,21993).
xc_kb_names(a65b16517ac598,[]).
xc_mapping_rows(a65b16517ac598,[]).
x_comment(x_parserSpecificationLexicalMicrotheory,"<code>(#$parserSpecificationLexicalMicrotheory SPECIFICATION MT)</code> means that when a parser is called according to the parsing specification <code>SPECIFICATION</code>, lexical information is accessed from <code>MT</code>, an instance of #$Microtheory. For example, if \"attest\" is parsed according to SPECIFICATION such that <code>(#$parserSpecificationLexicalMicrotheory SPECIFICATION #$GermanLexicalMt)</code>, only entries for #$Attest-TheWord found in that Mt (as opposed to #$EnglishMt, for example) will be considered.") :- x_cid(a65b16517ac599).
xc_microtheory(a65b16517ac599,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac599,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517ac599,21994).
xc_kb_names(a65b16517ac599,[]).
xc_mapping_rows(a65b16517ac599,[]).
x_comment(x_programSpecificationMaxTime,"<code>(#$programSpecificationMaxTime SPECIFICATION TIME)</code> means that when a program is called according to the specification <code>SPECIFICATION</code>, it is set to run for a length of time no longer than <code>TIME</code>, an instance of #$Time-Quantity.") :- x_cid(a65b16517ac59a).
xc_microtheory(a65b16517ac59a,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac59a,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
