xc_mapping_rows(a65b16517ac60f,[]).
x_comment(x_USGSTopographicMapNamedFn,"<code>(#$USGSTopographicMapNamedFn NAME)</code> denotes the #$USGSTopographicMap identified by <code>NAME</code>. See also the corresponding predicate #$nameStringForUSGSTopoMap.") :- x_cid(a65b16517ac610).
