xc_mapping_rows(a65b16517ac611,[]).
x_comment(x_USGSTopographicMap,"Each #$USGSTopographicMap is a #$TopographicMap published by the #$USGeologicalSurvey and which depicts a portion of the #$UnitedStatesOfAmerica or one of its territories.  These maps range in scale from 1:20,000 to 1:250,000.   Each #$USGSTopographicMap is identified by a name string derived from the name of a prominent depicted feature appended with the two-letter abbreviation for the state or territory in which the depicted region lies, e.g. \"Chalk Mountain, CO\".") :- x_cid(a65b16517ac612).
xc_microtheory(a65b16517ac612,x_UniversalVocabularyMt).
xc_source_file(a65b16517ac612,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
xc_source_line(a65b16517ac612,22252).
xc_kb_names(a65b16517ac612,[]).
xc_mapping_rows(a65b16517ac612,[]).
x_comment(x_ExplosiveDeviceDisposalSpecialist,"A #$PersonTypeByActivity.  Each instance of #$ExplosiveDeviceDisposalSpecialist is a #$Person who specializes in safely disposing of #$ExplosiveDevices such as #$Bombs.  Such a person may, but need not, be a #$MilitaryPerson.") :- x_cid(a65b16517ac613).
xc_microtheory(a65b16517ac613,x_UniversalVocabularyMt).
