xc_kb_names(a65b16517acd54,[]).
xc_mapping_rows(a65b16517acd54,[]).
x_comment(x_ambientCondition,"The predicate #$ambientCondition is used to describe the ambient conditions at a particular outdoor location.  <code>(#$ambientCondition LOC COND)</code> means that the #$OutdoorLocation <code>LOC</code> is an instance of the #$OutdoorLocationTypeByAmbientCondition <code>COND</code>.") :- x_cid(a65b16517acd55).
