xc_mapping_rows(a65b16517ace73,[]).
x_comment('x_synonymousExternalPred-Inverse',"A ternary predicate that relates an instance of #$BinaryPredicate to a term that occurs in a data source, <code>(#$synonymousExternalPred-Inverse PRED SOURCE STRING)</code> means that the predicate <code>PRED</code> is the co-inverse of a predicate <code>OTHER-PRED</code> (i.e., <code>(#$inverseBinaryPredicateOf PRED-1 PRED-2)</code> holds) such that, within the data source <code>SOURCE</code>, the string <code>STRING</code> denotes <code>OTHER-PRED</code>.") :- x_cid(a65b16517ace74).
