xc_mapping_rows(a65b16517ad288,[]).
x_comment(x_projectSeedlings,"<code>(#$projectSeedlings PROJECT SEEDLING)</code> means that the instance <code>SEEDLING</code> of #$Project was a seedling effort done to support the successful launch of the project <code>PROJECT</code>.") :- x_cid(a65b16517ad289).
