x_comment(x_MilitaryEvent,"The collection of all military events, including #$War, #$Battles, #$Explosions, and military #$Training.  Note that these events need not be organized or planned, just connected to the military in some way.") :- x_cid(a65b16517ad28c).
xc_microtheory(a65b16517ad28c,x_UniversalVocabularyMt).
xc_source_file(a65b16517ad28c,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part06.krf').
