xc_mapping_rows(a65b16517ad586,[]).
x_comment(x_marketQuantityDemandAtConsumerIncomeLevel,"<code>(#$marketQuantityDemandAtConsumerIncomeLevel MARKET PRODUCT INCOME QUANTITY)</code> identifies <code>QUANTITY</code> as the quantity of demanded goods or services of type <code>PRODUCT</code> for consumers at an income level of <code>INCOME</code>, an instance of #$MonetaryValue.") :- x_cid(a65b16517ad587).
xc_microtheory(a65b16517ad587,x_UniversalVocabularyMt).
